package io.knowledgebrain.collaboration;
import java.time.Clock;
import java.util.*;
import java.util.concurrent.*;
import org.flywaydb.core.Flyway;
import org.postgresql.ds.PGSimpleDataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import static org.assertj.core.api.Assertions.*;
import io.knowledgebrain.contracts.collaboration.group.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class GroupStoreIntegrationTest {
 PGSimpleDataSource source;JdbcTemplate jdbc;GroupStore store;UuidV7 ids=new UuidV7(Clock.systemUTC());String trace="a".repeat(32);UUID owner;
 String key(){return UUID.randomUUID().toString().replace("-","");}
 @BeforeEach void setup(){source=new PGSimpleDataSource();source.setURL(System.getenv("BRAIN_TEST_COLLABORATION_DATABASE_URL"));source.setUser("brain_collaboration");source.setPassword(System.getenv("BRAIN_TEST_COLLABORATION_DATABASE_PASSWORD"));Flyway.configure().dataSource(source).load().migrate();jdbc=new JdbcTemplate(source);store=new GroupStore(source,Clock.systemUTC());owner=ids.next();}
 @Test void completeSnapshotsAndImmutableEvents()throws Exception{var g=store.request(owner,key(),"스터디 <script>","개인 데이터 자동 공유 없음",trace);assertThat(g.state()).isEqualTo("PENDING");assertThat(g.spaceId()).isNull();var space=ids.next();var active=store.activate(g.groupId(),owner,space,trace);assertThat(active.version()).isEqualTo(2);assertThat(store.history(g.groupId(),Long.MAX_VALUE,10)).extracting(GroupStore.Revision::version).containsExactly(2L,1L);var events=jdbc.queryForList("SELECT payload FROM outbox_event WHERE aggregateid=? ORDER BY occurred_at,id",byte[].class,g.groupId());assertThat(events).hasSize(2);var states=new HashSet<String>();for(var bytes:events){var e=EventEnvelopeV1.parseFrom(bytes);assertThat(UUID.fromString(e.getEventId()).version()).isEqualTo(7);assertThat(e.getTraceId()).isEqualTo(trace);assertThat(e.getActorId()).isEqualTo(owner.toString());var p=GroupSnapshotV1.parseFrom(e.getPayload());assertThat(p.getVisibility()).isEqualTo("PRIVATE");assertThat(p.getTitle()).isEqualTo(g.title());assertThat(e.hasSpaceId()).isEqualTo(p.hasSpaceId());states.add(p.getState());}assertThat(states).containsExactlyInAnyOrder("PENDING","ACTIVE");}
 @Test void sameKeySurvivesRestartAndRejectsChangedInput(){var key=key();var g=store.request(owner,key,"same","",trace);var restarted=new GroupStore(source,Clock.systemUTC());assertThat(restarted.request(owner,key,"same","",trace).groupId()).isEqualTo(g.groupId());assertThatThrownBy(()->restarted.request(owner,key,"different","",trace)).isInstanceOf(org.springframework.web.server.ResponseStatusException.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregateid=?",Long.class,g.groupId())).isEqualTo(1);}
 @Test void activeRetryDoesNotDuplicateRevisions(){var key=key();var g=store.request(owner,key,"x","",trace);var space=ids.next();store.activate(g.groupId(),owner,space,trace);assertThat(store.request(owner,key,"x","",trace).state()).isEqualTo("ACTIVE");store.activate(g.groupId(),owner,space,trace);assertThat(jdbc.queryForObject("SELECT count(*) FROM group_revision WHERE group_id=?",Long.class,g.groupId())).isEqualTo(2);assertThatThrownBy(()->store.activate(g.groupId(),owner,ids.next(),trace)).isInstanceOf(IllegalStateException.class);}
 @Test void concurrentCreateAndCompleteAreIdempotent()throws Exception{var key=key();try(var executor=Executors.newVirtualThreadPerTaskExecutor()){var tasks=new ArrayList<Future<GroupStore.Group>>();for(int i=0;i<6;i++)tasks.add(executor.submit(()->store.request(owner,key,"x","",trace)));var results=new ArrayList<GroupStore.Group>();for(var task:tasks)results.add(task.get(20,TimeUnit.SECONDS));assertThat(results.stream().map(GroupStore.Group::groupId).distinct().count()).isEqualTo(1);var group=results.getFirst().groupId();var space=ids.next();tasks.clear();for(int i=0;i<6;i++)tasks.add(executor.submit(()->store.activate(group,owner,space,trace)));for(var task:tasks)assertThat(task.get(20,TimeUnit.SECONDS).version()).isEqualTo(2);assertThat(jdbc.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregateid=?",Long.class,group)).isEqualTo(2);}}
 @Test void requestOutboxFailureRollsBackEverything(){assertThatThrownBy(()->store.request(owner,key(),"x","","0".repeat(32))).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(store.candidates(owner,null,10)).isEmpty();}
 @Test void failedActivationKeepsRecoverablePendingRequest(){var g=store.request(owner,key(),"x","",trace);var space=ids.next();assertThatThrownBy(()->store.activate(g.groupId(),owner,space,"0".repeat(32))).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(store.owned(g.groupId(),owner).state()).isEqualTo("PENDING");assertThat(store.history(g.groupId(),Long.MAX_VALUE,10)).hasSize(1);assertThat(new GroupStore(source,Clock.systemUTC()).activate(g.groupId(),owner,space,trace).state()).isEqualTo("ACTIVE");}
 @Test void ownKeysetPagesNeverExposeOtherCreators(){var other=ids.next();store.request(other,key(),"SECRET","",trace);for(int i=0;i<3;i++)store.request(owner,key(),"same name","",trace);var rows=store.candidates(owner,null,2);assertThat(rows).hasSize(3);assertThat(store.candidates(owner,rows.get(1).groupId(),2)).extracting(GroupStore.Group::groupId).containsExactly(rows.get(2).groupId());assertThatThrownBy(()->store.owned(rows.getFirst().groupId(),other)).isInstanceOf(org.springframework.web.server.ResponseStatusException.class);}
}
